ew(0,20,0,20)minusBtn.Position=UDim2.new(1,-74,0.5,-10)minusBtn.BackgroundColor3=Color3.fromRGB(0,0,0)minusBtn.BackgroundTransparency=0.85 minusBtn.Text="-"minusBtn.TextColor3=Color3.fromRGB(0,0,0)minusBtn.Font=Enum.Font.SourceSansBold minusBtn.ZIndex=3 minusBtn.Parent=frame local textBox=Instance.new("TextBox")textBox.Size=UDim2.new(0,30,0,20)textBox.Position=UDim2.new(1,-50,0.5,-10)textBox.BackgroundColor3=Color3.fromRGB(255,255,255)textBox.BackgroundTransparency=0.3 textBox.Text=string.format("%.1f",TUNE_SETTINGS[settingKey])textBox.TextColor3=Color3.fromRGB(0,0,0)textBox.TextSize=12 textBox.Font=Enum.Font.SourceSansBold textBox.ClearTextOnFocus=false textBox.ZIndex=3 textBox.Parent=frame local plusBtn=Instance.new("TextButton")plusBtn.Size=UDim2.new(0,20,0,20)plusBtn.Position=UDim2.new(1,-16,0.5,-10)plusBtn.BackgroundColor3=Color3.fromRGB(0,0,0)plusBtn.BackgroundTransparency=0.85 plusBtn.Text="+"plusBtn.TextColor3=Color3.fromRGB(0,0,0)plusBtn.Font=Enum.Font.SourceSansBold plusBtn.ZIndex=3 plusBtn.Parent=frame Instance.new("UICorner",minusBtn).CornerRadius=UDim.new(0,4)Instance.new("UICorner",textBox).CornerRadius=UDim.new(0,4)Instance.new("UICorner",plusBtn).CornerRadius=UDim.new(0,4)local function updateValue(newVal)newVal=math.max(1.0,newVal)TUNE_SETTINGS[settingKey]=newVal textBox.Text=string.format("%.1f",newVal)end minusBtn.MouseButton1Click:Connect(function()updateValue(TUNE_SETTINGS[settingKey]-step)end)plusBtn.MouseButton1Click:Connect(function()updateValue(TUNE_SETTINGS[settingKey]+step)end)textBox.FocusLost:Connect(function()local num=tonumber(textBox.Text)if num then updateValue(num)else textBox.Text=string.format("%.1f",TUNE_SETTINGS[settingKey])end end)end local function tuneVehicle(vehicle)if not vehicle or vehicle:FindFirstChild("AlreadyECUTuned")then return end local tag=Instance.new("BoolValue")tag.Name="AlreadyECUTuned"tag.Parent=vehicle for _,obj in ipairs(vehicle:GetDescendants())do if obj:IsA("NumberValue")or obj:IsA("IntValue")then local name=obj.Name:lower()if name:find("torque")or name:find("accel")or name:find("horsepower")or name:find("power")or name:find("force")then obj.Value=obj.Value*TUNE_SETTINGS.TorqueMultiplier elseif name:find("rev")or name:find("rpm")or name:find("redline")then obj.Value=obj.Value*TUNE_SETTINGS.RevLimitBoost end end if obj:IsA("VehicleSeat")then obj.Torque=obj.Torque*TUNE_SETTINGS.TorqueMultiplier end end for attrName,attrValue in pairs(vehicle:GetAttributes())do if type(attrValue)=="number"then local name=attrName:lower()if name:find("torque")or name:find("accel")or name:find("power")or name:find("force")then vehicle:SetAttribute(attrName,attrValue*TUNE_SETTINGS.TorqueMultiplier)end end end end createValueAdjuster("แรงบิด/อัตราเร่ง","TorqueMultiplier",0.2,1)createValueAdjuster("รอบเครื่องยนต์","RevLimitBoost",0.2,2)local ManualBtn=Instance.new("TextButton")ManualBtn.Size=UDim2.new(1,0,0,28)ManualBtn.BackgroundColor3=Color3.fromRGB(255,120,0)ManualBtn.BackgroundTransparency=0.1 ManualBtn.Text="จูนรถคันนี้ทันที"ManualBtn.TextColor3=Color3.fromRGB(255,255,255)ManualBtn.TextSize=12 ManualBtn.Font=Enum.Font.SourceSansBold ManualBtn.LayoutOrder=3 ManualBtn.ZIndex=3 ManualBtn.Parent=Container Instance.new("UICorner",ManualBtn).CornerRadius=UDim.new(0,8)ManualBtn.MouseButton1Click:Connect(function()local char=player.Character if char then local humanoid=char:FindFirstChildOfClass("Humanoid")if humanoid and humanoid.SeatPart then local vehicle=humanoid.SeatPart:FindFirstAncestorOfClass("Model")or humanoid.SeatPart.Parent if vehicle then local oldTag=vehicle:FindFirstChild("AlreadyECUTuned")if oldTag then oldTag:Destroy()end tuneVehicle(vehicle)end end end end)local InfoLabel=Instance.new("TextLabel")InfoLabel.Size=UDim2.new(1,0,0,38)InfoLabel.BackgroundTransparency=1 InfoLabel.Text="วิธีใช้งาน: เลือกว่าจะจูนอะไรเท่าไหนก่อนแล้วก็กดจูนรถคันนี้ทันที แล้วเสกรถออกมา"InfoLabel.TextColor3=Color3.fromRGB(50,50,60)InfoLabel.TextSize=10 InfoLabel.Font=Enum.Font.SourceSans InfoLabel.TextWrapped=true InfoLabel.TextYAlignment=Enum.TextYAlignment.Top InfoLabel.LayoutOrder=4 InfoLabel.ZIndex=3 InfoLabel.Parent=Container local function onCharacterAdded(char)local humanoid=char:WaitForChild("Humanoid",10)if humanoid then humanoid.Seated:Connect(function(isSeated,seat)if isSeated and seat then local vehicle=seat:FindFirstAncestorOfClass("Model")or seat.Parent if vehicle then tuneVehicle(vehicle)end end end)end end if player.Character then onCharacterAdded(player.Character)end player.CharacterAdded:Connect(onCharacterAdded)
